window.docContents[192].resolve({"/Aula-1___-Motiva______o-e-L___gica-Proposicional/Exemplos-Resolvidos/#Verifica______o-Formal-de-Software--Aula-1___-Motiva______o-e-L___gica-Proposicional--Exemplos-Resolvidos--Elimina______o-da-Dupla-Nega______o":{"contents":"Esta direção requer raciocínio clássico. Classical.byContradiction descarta a suposição ¬P após derivar ⊥ dela junto com ¬¬P.O passo clássico marcado RAA é reductio ad absurdum, latim para \"redução ao absurdo\".\n\n   [¬P]  [¬¬P]\n  ──────────────  ¬E\n        ⊥\n    ──────────  RAA\n        P\n   ───────────────  →I\n     ¬¬P → P\n\n\nexample (P : Prop) : ¬¬P → P :=\n  fun h => Classical.byContradiction (fun hnP => h hnP)\n\n\nexample (P : Prop) : ¬¬P → P := by\n  intro h\n  apply Classical.byContradiction\n  intro hnP\n  exact h hnP\n\n\n","context":"Verificação Formal de Software\u0009Aula 1: Motivação e Lógica Proposicional\u0009Exemplos Resolvidos","header":"1.8.5. Eliminação da Dupla Negação","id":"/Aula-1___-Motiva______o-e-L___gica-Proposicional/Exemplos-Resolvidos/#Verifica______o-Formal-de-Software--Aula-1___-Motiva______o-e-L___gica-Proposicional--Exemplos-Resolvidos--Elimina______o-da-Dupla-Nega______o"}});